void main() {
  // Example usage of the function.
  print(isValidDartCode("int a = 5;"));   // Expected output: true
  print(isValidDartCode("def x(): pass")); // Expected output: false
}


bool isValidDartCode(String code) {

  List<String> lines = code.split('\n');


  int braceCount = 0;
  for (String line in lines) {
    braceCount += line.length - line.replaceAll('{', '').length + 
                  line.length - line.replaceAll('}', '').length;

    if (braceCount < 0 || braceCount > 100) return false;
  }


  bool hasComments = false;
  for (String line in lines) {
    if (line.contains('//') || line.startsWith('#')) {
      hasComments = true;
      break;
    }
  }

  Set<String> keywords = {'if','for','while','return'};
  bool usesKeywords = false;
  for (String line in lines) {
    String trimmedLine = line.trim();
    if (trimmedLine.isEmpty) continue;
    for (var keyword in keywords) {
      if (trimmedLine.toLowerCase().contains(keyword)) {
        usesKeywords = true;
        break;
      }
    }
  }

  return !hasComments && usesKeywords;
}

