func computeAndPrint(aStr, bStr string) {
	a := toInt(aStr)
	b := toInt(bStr)
	diff := a - b
	product := a * b
	quotient := float64(a) / float64(b) // 假设b不为零
	fmt.Printf("%d\n%d\n%.2f\n", diff, product, quotient)
}

