  if (args.isEmpty) {
    print('Usage: dart <script_name>.dart');
    exit(1);
  }

  String scriptName = args[0];
  File file = File(scriptName);
  List<String> lines = file.readAsLinesSync();

  int index = -1;
  for (int i = 0; i < lines.length; i++) {
    if (lines[i].startsWith("void ")) {
      index = i;
      break;
    }
  }

  if (index == -1 || lines[index] != "void main()") {
    print('$scriptName does not have a valid entry point.');
    exit(1);
  }

  int start = 0, end = lines.length;

  while (start + 2 <= end && lines[start]!.endsWith('{') && lines[end - 1]!.endsWith('}')) {
    final countOpenBraces = (lines[start]!..removeRange(lines[start]!.length - 1)..trim()).replaceAll('{', '').length;
    final countCloseBraces = (lines[end - 1]!..removeRange(0)..trim()).replaceAll('}', '').length;

    if (countOpenBraces > countCloseBraces) {
      start++;
    } else if (countOpenBraces < countCloseBraces) {
      end--;
    } else {
      // Count nested braces to determine the exact range of the function body
      int level = 0;
      bool insideFunction = false;
      for (int j = start; j < end; j++) {
        if (!insideFunction && lines[j]!.contains("void")) {
          insideFunction = true;
        }
        if (insideFunction) {
          if (lines[j]!.contains('{')) {
            level += lines[j]!.split('{').length - 1;
          }
          if (lines[j]!.contains('}') && level > 0) {
            level -= lines[j]!.split('}').length - 1;
          }
          if (level == 0) {
            end = j;
            break;
          }
        }
      }
    }
  }

  final List<String> content = lines.sublist(start, end).join('\n');
  file.writeAsString(content, mode: FileMode.append);

  file.close();
}

