// 1. Find the first occurrence of each number in nums and store it in a map.
// 2. For every pair (i, j), check if nums[i] + nums[j] == target.
// 3. If so, record i as the smaller index and j as the larger one to avoid duplicates.
// 4. Return all valid pairs sorted by their indices.


func twoSum(nums []int, target int) [][]int {
	firstOccurrence := make(map[int]int) // maps value -> earliest index
	for i, num := range nums {
		if _, exists := firstOccurrence[num]; !exists {
			firstOccurrence[num] = i
		}
	}

	var result [][]int

	for i := 0; i < len(nums); i++ {
		complement := target - nums[i]
		if secondIndex, ok := firstOccurrence[complement]; ok && i != secondIndex {
			if i > secondIndex {
				result = append(result, []int{secondIndex, i})
			} else {
				result = append(result, []int{i, secondIndex})
			}
		}
	}

	return result
}



