List<String> _buffer = [];
int maxLen = 20;

void main() {
  String input;

  while ((input = stdin.readLineSync()) != null) {
    if (input == '') break;

    int sum = 0, product = 1;
    bool hasZero = false, allOdd = true;
    List<int> digits = [];
    for (String ch in input.split('')) {
      int d = int.tryParse(ch);
      if (d != null && d >= 0 && d <= 9) {
        digits.add(d);
        sum += d;
        product *= d;

        if (d % 2 == 0) allOdd = false;
        if (d == 0) hasZero = true;
      } else {
        print(_interpolate(
          "Invalid character \${ch} at position ${_buffer.length + 1}", 
          {'length': _buffer.length + 1},
        ));
        return;
      }

      _buffer.add(input.substring(_buffer.length));
      if (_buffer.length > maxLen) {
        _buffer.removeAt(0);
      }
    }

    bool isPalindrome = digits.isEmpty || 
                        [for (var i in digits.reversed) i]..toList() == digits;
    bool contains3Or5 = digits.any((x) => x == 3 || x == 5);
    int countThreeFive = digits.where((x) => x == 3 || x == 5).length;
    int length = digits.length;

    if (!isPalindrome) {
      print("The sequence is not a palindrome.");
    } else if (contains3Or5) {
      print("${countThreeFive} occurrences of the digits 3 or 5");
    } else {
      print(_interpolate(
        "${sum} and ${product}. All odd? $allOdd. Has zero? $hasZero",
        {},
      ));
    }
  }
}

String _interpolate(String text, Map<String, dynamic> args) {
  for (MapEntry<String, dynamic> entry : args.entries) {
    text = text.replaceAll('\$entry.key', entry.value.toString());
  }
  return text;
}

