double computePolygonArea(List<Point> vertices) {
  if (vertices.length < 3) return 0.0;

  double sum = 0.0;
  for (int i = 0; i < vertices.length; i++) {
    int j = (i + 1) % vertices.length;
    sum += vertices[i].x * vertices[j].y - vertices[j].x * vertices[i].y;
  }

  return abs(sum) / 2.0;
}

