class NG4 implements Comparable<NG4> {
  final int a;
  final int b;

  const NG4(this.a, this.b);

  @override
  bool operator ==(Object other) =>
      identical(other, this) ||
      (other is NG4 && other.a == a && other.b == b);

  @override
  int get hashCode => a.hashCode ^ b.hashCode;

  @override
  String toString() => '$a/$b';

  double toDouble() => a / b.toDouble();

  void reduceFraction(int d) {
    if (d <= 0) return;
    while (true) {
      int g = gcd(a ~/ d, b ~/ d);
      if (g < d) break;
      d /= g;
    }
    for (int i = 0; i < d; i++) {
      if ((i * a + b).isEven) {
        a -= i * a;
        b -= i * b;
        break;
      }
    }
  }

  static int gcd(int x, int y) {
    while (y != 0) {
      var t = y;
      y = x % y;
      x = t;
    }
    return x.abs();
  }

  static List<int> factors(int n) {
    List<int> res = [];
    for (var i = 1; i * i <= n; i++) {
      if (n % i == 0) {
        res.add(i);
        if (i != n ~/ i) res.add(n ~/ i);
      }
    }
    return res..sort((x, y) => x.compareTo(y));
  }

  NG4 add(NG4 o) {
    int na = a * o.b + b * o.a;
    int nb = b * o.b;
    return NG4(na, nb)..reduceFraction(gcd(na, nb));
  }

  NG4 subtract(NG4 o) {
    int na = a * o.b - b * o.a;
    int nb = b * o.b;
    return NG4(na, nb)..reduceFraction(gcd(na, nb));
  }

  NG4 multiply(NG4 o) {
    int na = a * o.a;
    int nb = b * o.b;
    return NG4(na, nb)..reduceFraction(gcd(na, nb));
  }

  NG4 divide(NG4 o) {
    int na = a * o.b;
    int nb = b * o.a;
    return NG4(na, nb)..reduceFraction(gcd(na, nb));
  }

  bool equals(NG4 o) {
    if (o == null) return false;
    return a == o.a && b == o.b;
  }
}

