List<String> parseConfig(String config) {
  List<List<String>> lines = [];
  for (String line in config.split('\n')) {
    if (!line.startsWith('[')) continue;
    String content = line.substring(1, line.length - 2);
    List<String> entries = [];
    for (String item in content.trim().split(',')) {
      int idx = item.indexOf(':');
      if (idx != -1) {
        entries.add('${item.substring(0, idx).trim()}=${item.substring(idx + 1)}'.trim());
      } else {
        entries.add(item.trim());
      }
    }
    lines.add(entries);
  }
  return lines;
}

bool isValid(List<String> entry) {
  if (entry.isEmpty || !entry.contains('=')) {
    print('Warning: Invalid format "$entry"');
    return false;
  }
  try {
    Map<String, dynamic> kv = {};
    for (String part in entry.split('=')) {
      kv[part] = true;
    }
    bool hasKey = false;
    for (var key in kv.keys) {
      hasKey |= ['key', 'value'].contains(key.toLowerCase());
    }
    return hasKey && kv.values.every((v) => v is bool && v == true);
  } catch (_) {
    return false;
  }
}

void main() async {
  final configFile = File('./config.txt');
  final input = await configFile.readAsString();

  List<List<String>> rows = parseConfig(input);

  var validLines = <List<String>>[];
  for (int i = 0; i < rows.length; i++) {
    if (isValid(rows[i])) {
      validLines.add(rows[i]);
    } else {
      print('Skipping invalid row at index $i: ${rows[i].join(',')}');
    }
  }

  if (validLines.isEmpty) {
    print('No valid configuration found.');
    exit(0);
  }

