List<List<int>> findPath(int start, int end) {
  List<List<int>> paths = [];

  void backtrack(List<int> path, int current) {
    if (current == end) {
      paths.add([...path]); // Add a copy of the valid path
      return;
    }

    for (int i in [start - 1, start + 2]) {
      if (i >= 0 && i < end + 1) {
        path.add(i);
        backtrack(path, i);
        path.removeLast(); // Backtrack to try other branches
      }
    }
  }

  backtrack([start], start);
  return paths;
}

