    }

    if (cycles.isEmpty) {
      return 'Acyclic directed forest';
    }

    var cycleDesc = '';
    for (int cRoot in cycles) {
      if (cycleDesc.isNotEmpty) cycleDesc += ', ';

      bool[] seenInCycle = [false] * n;
      bool[] active = [true] * n;
      Queue<int> q = Queue([cRoot]);
