        if (!active[cRoot]) continue;

        for (var edge in adjList[curr]) {
          int next = edge.to! - 1;

          if (seenInCycle[next]) continue;

          if (edge.from != null) {
            seenInCycle[next] = true;

            if (active[next]) {
