    final dist = List<int>.filled(leftSize + rightSize, -1);
    List<bool> visitedLeft = [false] * leftSize;
    bool bfs() {
      for (int i = 0; i < leftSize; i++) {
        if (_adjacency[i].isEmpty && !visitedLeft[i]) return true;
        if (!visitedLeft[i]) {
          visitedLeft[i] = true;
          for (final e in _adjacency[i]) {
            final matchedIndex = e.toRightNode();
            if (dist[matchedIndex] == -1) {
              dist[matchedIndex] = dist[e.fromLeftNode()]! + 1;
            } else if (dist[matchedIndex] != dist[e.fromLeftNode()]! + 1) {
              return false;
            }
          }
        }
      }
      return true;
    }

    bool dfs(int u) {
      for (final e in _adjacency[u]) {
        final matchedIndex = e.toRightNode();
        if (dist[matchedIndex] == dist[e.fromLeftNode()]! + 1 && dfs(matchedIndex)) {
