String solve(List<List<String>> grid) {
  int rows = grid.length;
  if (rows == 0 || rows % 2 != 1) return 'Invalid grid size';

  int cols = grid[0].length;
  if (cols == 0 || cols % 2 != 1) return 'Invalid column size';

  List<int> countUp = [];
  for (int i = 0; i < rows; i++) {
    countUp.add(0);
  }

  List<int> countRight = [];
  for (int j = 0; j < cols; j++) {
    countRight.add(0);
  }

  bool valid = true;
  for (int i = 0; i < rows; i++) {
    for (int j = 0; j < cols; j++) {
      if ((i + j).isEven && grid[i][j] != ('a' * (countUp[i]++))) {
        valid = false; break;
      } else if ((i + j).isOdd && 
                !grid[i][j].startsWith(('b' * countRight[j]).substring(countRight[j]))) {
        valid = false; break;
      }
    }
    if (!valid) break;
  }

  return valid ? 'Valid pattern found!' : 'Pattern not consistent';
}

