class TestCase {
  final List<int> rows;
  final int targetSum;
  bool passed;

  TestCase(this.rows, this.targetSum) : passed = false;
}

List<TestCase> parseInput(String input) {
  final lines = input.split('\n');
  final tests = <TestCase>[];
  for (int i = 0; i < lines.length - 1; i += 3) {
    final rowStrs = lines[i].split(',').map(int.parse).toList();
    final sumLine = lines[i + 1].trim().split(' ')[1];
    final target = int.parse(sumLine);
    final test = TestCase(rowStrs, target);
    test.passed = _checkRows(test.rows, test.targetSum);
    tests.add(test);
  }
  return tests;
}

bool _checkRows(List<int> rows, int target) {
  if (rows.isEmpty || rows.length % 2 != 0) return false;

  final half = rows.length ~/ 2;
  List<List<int>> pairs = [];

  for (int i = 0; i < half; i++) {
    final p1 = rows[i];
    final p2 = rows[half + i];

    // Check if they form a valid pair
    if ((p1 & 1) == (p2 & 1)) continue; // Same parity

    if (pairs.contains([p1, p2]) || 
        pairs.contains([p2, p1])) {
      return false; // Duplicate pair found in reverse order
    }

    pairs.add([p1, p2]);
  }

  // Sort pairs to ensure consistent ordering
  pairs.sort((a, b) => a[0] > b[0] ? 1 : -1);

  // Verify all elements are used exactly once and no duplicates exist
  final flattened = pairs.expand((pair) => pair.toList()).toList()..sort();
  final uniqueFlattened = List.from(flattened)..removeDuplicates();

  if (uniqueFlattened.length != flattened.length) {
    return false; // Duplicates detected after sorting
  }

  int currentSum = 0;
  for (final pair in pairs) {
    if (_isPairValid(pair)) {
      currentSum += pair.reduce(max);
    } else {
      return false; // Invalid pair logic encountered
    }
  }

  return currentSum >= target && 
         !flattened.any((val) => val % 2 == 0); // No even numbers allowed
}

bool _isPairValid(List<int> pair) {
  final (a, b) = pair;

  if (a == 0 || b == 0) return true; // Zero values handled directly

  if (a * 2 > b) return false;

  while (b % 2 == 0) b /= 2;

  while (a % 2 == 0) a /= 2;

  return a <= b;
}

