List<List<Facet>> prepareConvexHulls(List<List<Point>> polygons) {
  if (polygons.isEmpty || polygons.any((pts) => pts.length < 3)) return [];

  for (var poly in polygons) {
    var n = poly.length;
    if (n < 3) continue;

    poly.sort(
      (a, b) => a.y.compareTo(b.y) == 0 ? a.x.compareTo(b.x) : a.y.compareTo(b.y),
    );

    var hull = <Point>[poly[0], poly[n-1]];
    for (int i = 1; i < n - 1; i++) {
      var cross = (hull.last - hull.first).cross(poly[i] - hull.first);
      if (cross <= 0.0) continue;

      var dir = poly[i].y > hull.last.y ? 1 : -1;
      while (dir != 0) {
        int j = hull.indexWhere((pt) => pt.y > poly[i].y + 1e-9);
        if (j != -1) {
          hull.removeAt(j);
          dir *= -1;
        } else break;
      }

      hull.add(poly[i]);
    }

    var facets = <Facet>[];
    for (int i = 0; i < hull.length; i++) {
      var f = Facet(hull[(i+1)%hull.length], hull[i]);
      facets.addAll(f.points.map((pt) => facetCopy(f)));
    }

    polygons[polygons.indexOf(poly)] = facets.cast();
  }

  return polygons.where((facets) => facets.isNotEmpty).toList();
}

Facet facetCopy(Facet original) => Facet(original.p0, original.p1)..points = [...original.points];

