// ShuntingYard implementation in Dart

class ShuntingYard {
  /// Convert an infix expression to postfix (RPN) format.
  static String toPostfix(String expression) {
    final tokens = _tokenize(expression);
    final output = <String>[];
    final operators = <String>['+', '-', '*', '/', '^']; // support ^ for exponentiation

    for (final token in tokens) {
      if (_isNumber(token)) {
        output.add(token);
      } else if (_isOperator(token, operators)) {
        while (_hasPrecedence(output.last, token, operators)) {
          output.removeLast();
          output.add(output.removeLast());
        }
        output.add(token);
      } else if (_isOpenParenthesis(token)) {
        output.add(token);
      } else if (_isCloseParenthesis(token)) {
        while (!(_isOpenParenthesis(output.last))) {
          output.add(output.removeLast());
        }
        output.removeLast(); // discard '('
      }
    }

    while (output.isNotEmpty) {
      output.add(output.removeLast());
    }

    return output.join(' ');
  }

  static bool _isOpenParenthesis(String s) => s == '(';
  static bool _isCloseParenthesis(String s) => s == ')';
  static bool _isNumber(String s) => double.tryParse(s) != null;
  static bool _isOperator(String s, List<String> validOps) => 
      validOps.contains(s) || s.isEmpty; // empty string is a terminator

  static bool _hasPrecedence(String op1, String op2, List<String> ops) {
    int p1 = _precedence(op1, ops);
    int p2 = _precedence(op2, ops);
    return p1 > p2 || (p1 == p2 && op2 == '^'); // left-associative except ^
  }

  static int _precedence(String op, List<String> ops) {
    switch (op) {
      case '+':
      case '-':
        return 1;
      case '*':
      case '/':
        return 2;
      case '^':
        return 3;
      default:
        return 0;
    }
  }

  static List<String> _tokenize(String expr) {
    final result = <String>[];
    final parts = expr.split(RegExp(r'\s+'));
    for (int i = 0; i < parts.length; ) {
      final part = parts[i];
      if (_isNumber(part)) {
        result.addAll(_extractNumbers(part));
        i++;
      } else {
        result.add(part);
        i++;
      }
    }
    return result;
  }

  static List<String> _extractNumbers(String numStr) {
    final numbers = <String>[];
    for (int start = 0; ; ) {
      if (!_isDigit(numStr[start])) break;
      int end = start + 1;
      while (end < numStr.length && _isDigit(numStr[end])) end++;
      numbers.add(numStr.substring(start, end));
      start = end;
    }
    return numbers;
  }

  static bool _isDigit(String ch) => ch.codeUnitAt(0).toString().length == 1;
}


