class Node {
  int key;
  Node left, right;
  int height = 1; // Height of the node (number of nodes on the longest path from this node to a leaf)

  Node(this.key);
}


class AVLTree {
  Node root;

  void insert(int key) {
    _insert(root, key);
  }

  int _height(Node n) => n == null ? 0 : n.height;

  int _balanceFactor(Node n) {
    if (n == null) return 0;
    return _height(n.left) - _height(n.right);
  }

  Node _minimum(Node n) {
    while (n.left != null) n = n.left;
    return n;
  }

  Node _rightRotate(Node y) {
    Node x = y.left!;
    Node T2 = x.right;

    x.right = y;
    y.left = T2;

    y.height = max(_height(y.left), _height(y.right)) + 1;
    x.height = max(_height(x.left), _height(x.right)) + 1;

    return x;
  }

  Node _leftRotate(Node x) {
    Node y = x.right!;
    Node T2 = y.left;

    y.left = x;
    x.right = T2;

    x.height = max(_height(x.left), _height(x.right)) + 1;
    y.height = max(_height(y.left), _height(y.right)) + 1;

    return y;
  }

  Node _insert(Node node, int key) {
    if (node == null) return Node(key);

    if (key < node.key) {
      node.left = _insert(node.left, key);
    } else if (key > node.key) {
      node.right = _insert(node.right, key);
    } else {
      return node; // Duplicate keys are not allowed
    }

    node.height = 1 + max(_height(node.left), _height(node.right));

    int balance = _balanceFactor(node);

    // Left Heavy
    if (balance > 1 && key < node.left!.key) {
      return _rightRotate(node);
    }

    // Right Heavy
    if (balance < -1 && key > node.right!.key) {
      return _leftRotate(node);
    }

    // Left-Right Case
    if (balance > 1 && key > node.left!.key) {
      node.left = _leftRotate(node.left!);
      return _rightRotate(node);
    }

    // Right-Left Case
    if (balance < -1 && key < node.right!.key) {
      node.right = _rightRotate(node.right!);
      return _leftRotate(node);
    }

    return node;
  }
}



