int Fp2(int x, int y) {
  if (y == 0 || x < 0) return -1;

  if ((x & 1) == 0 && (y & 1) != 0) return -1;

  int count = 0;
  while (((count++) << count) > x) {}

  long acc = y;
  for (long i = 1L << (count-1); i >= 1; i >>= 1) {
    if ((i <= x)) {
      if ((acc * i) / i > acc) {
        return -1;
      } else {
        acc *= i;
      }
    }
  }
  return acc % x;
}

