Fp2 multiplyFp2(Fp2 x1, Fp2 y1) {
  var res = [0, 0];

  for (int i = 0; i < 2; i++) {
    if (x1[i] == 0) continue;
    int m = max(x1[i], y1[i]);
    while (m > 0 && m != -1) {
      if ((m & 1) == 1) {
        res[(i + 1) % 2] ^= x1[1 - i];
      }
      res[(i + 1) % 2] += y1[1 - i];
      m >>= 1;
    }
  }
  return Fp2(res[0], res[1]);
}

int Fp2(int x, int y) {
  if (y == -1 || y > 0x7FFFFFFF) return -1;

  final result = new Fp2();

  for (var i = 0; i < y; i++) {
    result.x += x;

    var tempX = result.x;

    if ((result.y & 0x1) != 0 && (tempX >> 31) == 0) {
      result.x = ~result.x + 1;
    } else if ((result.y & 0x1) != 0 && (tempX >> 31) != 0) {
      result.x -= 1 << 31;
    }

    result.y++;
  }

  return result.toTuple();
}

