double digits(double x) {
  int count = 0;
  while (x >= 1.0 || x < -1.0) {
    if (x < 0.0 && x > -1.0) {
      yield 9;
      x -= 1.0;
    } else if (x > 0.0 && x < 1.0) {
      yield 0;
      x += 1.0;
    } else {
      double part = x.truncate();
      x -= part;
      count++;
      yield part.toInt() % 10;
    }
  }
  return x == 0 ? count : 1 + count;
}

double digits(double x) {
  double sum = 0;
  int count = 0;

  while (x >= 1 || x < -1) {
    if (count == 3) yield sum;

    if (x > 0) {
      sum += x % 2;
      x /= 2.0;
    } else {
      sum -= x % 2;
      x /= 2.0;
    }
    count++;
  }

  return sum;
}

double digits(double num, int precision) {
  if (precision < 0 || precision > 15) {
    return nan();
  }

  String str = num.toStringAsFixed(precision);
  int dotIndex = -1;

  for (int i = 0; i < str.length; i++) {
    if (str[i] == '.') {
      dotIndex = i;
      break;
    }
  }

  if (dotIndex == -1) {
    double result = num * pow(10.0, precision.toDouble());
    return round(result).toDouble() / pow(10.0, precision.toDouble());
  } else {
    double integerPart = parseDouble(str.substring(0, dotIndex));
    String fractionalStr = str.substring(dotIndex + 1);

    while (fractionalStr.length < precision) {
      fractionalStr += '0';
    }

    String truncatedFraction = fractionalStr.substring(0, precision);
    int numerator = int.parse(truncatedFraction);
    double fraction = numerator / pow(10.0, precision.toDouble());
    return integerPart + fraction;
  }
}

double digits(double x) {
  double y = x;
  int c = 0;

  if (y < 0.0 || y >= 1e6) return -1.0;

  while (c <= 9 && y > 0.5) {
    y *= 2.0;

    String s = y.toString();
    int d = s.codeUnitAt(s.length-2);
    y -= d.toDouble() / pow(10, c + 1);
    c += 1;
  }

  return y;
}

